/// Pinned identities every generated binding must carry.
pub(crate) struct BindingInputs<'input, 'catalog> {
    pub(crate) schema: Blake3Digest,
    pub(crate) registry: Blake3Digest,
    pub(crate) policy: Blake3Digest,
    pub(crate) golden_json: &'input str,
    pub(crate) golden_hash: Blake3Digest,
    pub(crate) authority_golden_hash: Blake3Digest,
    pub(crate) launch_grant_golden_hash: Blake3Digest,
    pub(crate) resolved: &'input ResolvedCatalogV1<'catalog>,
}

#[rustfmt::skip]
pub(crate) fn rust_constants(inputs: &BindingInputs<'_, '_>) -> Result<String, WireError> {
    let mut output = RUST_TEMPLATE
        .replace("@SCHEMA@", &inputs.schema.to_string())
        .replace("@REGISTRY@", &inputs.registry.to_string())
        .replace("@POLICY@", &inputs.policy.to_string())
        .replace("@GOLDEN_JSON@", inputs.golden_json)
        .replace("@GOLDEN_HASH@", &inputs.golden_hash.to_string())
        .replace("@AUTHORITY_GOLDEN_HASH@", &inputs.authority_golden_hash.to_string())
        .replace("@LAUNCH_GRANT_GOLDEN_HASH@", &inputs.launch_grant_golden_hash.to_string());
    if strict::is_required(inputs.resolved) {
        strict::render_rust(&mut output, inputs.resolved)?;
    } else {
        render_legacy_rust_records(&mut output, inputs.resolved)?;
    }
    Ok(output)
}

#[rustfmt::skip]
pub(crate) fn typescript_constants(inputs: &BindingInputs<'_, '_>) -> Result<String, WireError> {
    let BindingInputs { schema, registry, policy, golden_json, golden_hash, authority_golden_hash, launch_grant_golden_hash, resolved } = inputs;
    let encoded_golden = serde_json::to_string(golden_json).map_err(|error| {
        WireError::new("INVALID_CONTRACT_FIELD_REFERENCE", format!("canonical golden cannot be encoded: {error}"))
    })?;
    let mut output = format!(
        "// Generated by: bullet-wire-contract-tool v1alpha1\n\
// Source: contracts/v1alpha1 + policy/v1alpha1\n\
// Command: just contract-generate\n\
// DO NOT EDIT BY HAND.\n\
export const SCHEMA_VERSION = \"v1alpha1\" as const;\n\
export const SCHEMA_BUNDLE_HASH = \"{schema}\" as const;\n\
export const INVARIANT_REGISTRY_HASH = \"{registry}\" as const;\n\
export const POLICY_SNAPSHOT_HASH = \"{policy}\" as const;\n\
export const CANONICAL_GOLDEN_JSON = {encoded_golden} as const;\n\
export const CANONICAL_GOLDEN_HASH = \"{golden_hash}\" as const;\n\
export const AUTHORITY_GOLDEN_HASH = \"{authority_golden_hash}\" as const;\n\
export const LAUNCH_GRANT_GOLDEN_HASH = \"{launch_grant_golden_hash}\" as const;\n\
export type AuthorityAudienceV1 = \"bullet-gitd\" | \"effect-broker\" | \"provider-runner\";\n\
export type MutationOperationV1 = \"clone-workspace\" | \"read-workspace\" | \"apply-patch\" | \"checkpoint\" | \"prepare-candidate\" | \"preserve-workspace\" | \"cleanup-workspace\" | \"dispatch-effect\" | \"reconcile-effect\";\n\
export type AuthorityDecisionV1 = \"authorized\" | \"settled\" | \"refused\";\n\
export type ReplayDispositionV1 = \"fresh\" | \"exact-replay\" | \"conflict\";\n\
export type MutationResultStateV1 = \"in-flight\" | \"committed\" | \"aborted\" | \"unknown\";\n\
export type MutationOutcomeV1 = \"committed\" | \"aborted\" | \"unknown\";\n\
export type SettlementStatusV1 = \"accepted\" | \"exact-replay\" | \"conflict\" | \"refused\";\n\
export type PatchPreimageKindV1 = \"absent\" | \"digest\";\n\
export type PatchMutationKindV1 = \"write\" | \"delete\";\n\
export type ReleaseReceiptKindV1 = \"artifact\" | \"containment\" | \"forge\" | \"operations\" | \"profile-closure\" | \"provider\" | \"rust-toolchain\" | \"scanner\" | \"transaction\";\n\
export type ReleaseEvidenceKindV1 = \"artifact\" | \"audit-anchor\" | \"candidate\" | \"check\" | \"configuration\" | \"effect\" | \"environment\" | \"evidence\" | \"integration\" | \"jeryu\" | \"observation\" | \"platform\" | \"policy\" | \"profile-graph\" | \"proof-bundle\" | \"provider\" | \"provenance\" | \"sandbox\" | \"sbom\" | \"scanner\" | \"schema\" | \"toolchain\" | \"transaction\";\n\
export type ReleaseRegistryObjectKindV1 = \"gate-receipt\" | \"gate-receipt-signature\" | \"gate-spec\" | \"profile-graph\" | \"release-bundle-manifest-v2\" | \"signer-policy\" | \"trusted-time-observation\" | \"trusted-time-signature\" | \"verification-request\";\n\
export type ReleaseSignerRoleV1 = \"artifact-release\" | \"gate-attestor\" | \"registry-curator\" | \"source-tag\" | \"trusted-time\";\n\
export type ReleaseRepositoryNameV1 = \"bullet-farm\" | \"bullet-git\" | \"bullet-kernel\" | \"bullet-portal\";\n\
export type KeyPurposeV1 = \"authority-signing\" | \"release-signing\";\n\
export type KeyAlgorithmV1 = \"paseto-v4.public\" | \"ssh-ed25519\";\n"
    );
    if strict::is_required(resolved) {
        strict::render_typescript(&mut output, resolved)?;
    } else {
        render_legacy_typescript_records(&mut output, resolved)?;
    }
    Ok(output)
}

#[rustfmt::skip]
fn render_legacy_rust_records(output: &mut String, resolved: &ResolvedCatalogV1<'_>) -> Result<(), WireError> {
    for record in resolved.records() {
        output.push_str(&format!("\n#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]\n#[serde(deny_unknown_fields)]\npub struct {} {{\n", record.definition().name));
        for field in record.fields() {
            output.push_str(&format!("    pub {}: {},\n", field.definition().name, rust_type(field)?));
        }
        output.push_str("}\n");
    }
    Ok(())
}

#[rustfmt::skip]
fn render_legacy_typescript_records(output: &mut String, resolved: &ResolvedCatalogV1<'_>) -> Result<(), WireError> {
    for record in resolved.records() {
        output.push_str(&format!("\nexport interface {} {{\n", record.definition().name));
        for field in record.fields() {
            output.push_str(&format!("  {}: {};\n", field.definition().name, typescript_type(field)?));
        }
        output.push_str("}\n");
    }
    Ok(())
}

#[rustfmt::skip]
fn rust_type(field: &ResolvedFieldV1<'_>) -> Result<String, WireError> {
    match field.kind() {
        ResolvedFieldKindV1::LegacyValue => legacy_types(field.definition().field_type).map(|types| types.0.to_owned()).ok_or_else(impossible_field),
        ResolvedFieldKindV1::LegacyReference { shape, target } => {
            ensure_reference_shape(field.definition().field_type, shape)?;
            Ok(match shape { LegacyReferenceShapeV1::Direct => target.name().into(), LegacyReferenceShapeV1::Optional => format!("Option<{}>", target.name()), LegacyReferenceShapeV1::Array => format!("Vec<{}>", target.name()) })
        }
        ResolvedFieldKindV1::Named(_) | ResolvedFieldKindV1::OptionalNamed(_) | ResolvedFieldKindV1::BoundedArray { .. } | ResolvedFieldKindV1::BoundedSet { .. } => Err(impossible_field()),
    }
}

#[rustfmt::skip]
fn typescript_type(field: &ResolvedFieldV1<'_>) -> Result<String, WireError> {
    match field.kind() {
        ResolvedFieldKindV1::LegacyValue => legacy_types(field.definition().field_type).map(|types| types.1.to_owned()).ok_or_else(impossible_field),
        ResolvedFieldKindV1::LegacyReference { shape, target } => {
            ensure_reference_shape(field.definition().field_type, shape)?;
            Ok(match shape { LegacyReferenceShapeV1::Direct => target.name().into(), LegacyReferenceShapeV1::Optional => format!("{} | null", target.name()), LegacyReferenceShapeV1::Array => format!("{}[]", target.name()) })
        }
        ResolvedFieldKindV1::Named(_) | ResolvedFieldKindV1::OptionalNamed(_) | ResolvedFieldKindV1::BoundedArray { .. } | ResolvedFieldKindV1::BoundedSet { .. } => Err(impossible_field()),
    }
}

