#[rustfmt::skip]
fn ensure_reference_shape(field_type: FieldTypeV1, shape: LegacyReferenceShapeV1) -> Result<(), WireError> {
    use FieldTypeV1::*;
    use LegacyReferenceShapeV1::{Array, Direct, Optional};
    let actual = match field_type {
        RiskPolicy | EvidencePolicy | SandboxPolicy | BudgetPolicy | RoutePolicy | SignedAuthorityEnvelope | SignedMutationPermit | MutationReplayResult | ScopeGrant | PatchProposal | CleanupAuthorization | ReleaseFamilySubject => Some(Direct),
        OptionalSignedMutationPermit | OptionalMutationReplayResult => Some(Optional),
        IssuerKeyArray | PatchOperationArray | ReleaseRepositorySubjectArray | ReleaseEvidenceSubjectArray | ReleaseProfileNodeArray | ReleaseSignerKeyArray | ReleaseRegistryEntryArray | ReleaseRegistryObjectArray | ReleaseReplayBindingArray | ExecutionToolArray => Some(Array),
        _ => None,
    };
    if actual == Some(shape) { Ok(()) } else { Err(impossible_field()) }
}

#[rustfmt::skip]
fn impossible_field() -> WireError {
    WireError::new("INVALID_CONTRACT_FIELD_REFERENCE", "resolved field kind contradicts its private raw field kind")
}

#[rustfmt::skip]
#[derive(Default)]
struct StrictFeatures {
    arrays: bool, boolean: bool, bounds: bool, bounded_array: bool, bounded_set: bool,
    collect_array: bool, integer: bool, legacy_string: bool, pattern: bool, rebase: bool, set: bool,
    string: bool, text: bool, unique: bool,
}

#[rustfmt::skip]
fn strict_features(catalog: &ResolvedCatalogV1<'_>) -> StrictFeatures {
    let mut uses = StrictFeatures::default();
    for scalar in catalog.scalar_types() { match scalar.definition { ScalarDefinitionV1::SafeInteger { .. } => uses.integer = true, ScalarDefinitionV1::Text { .. } => { uses.string = true; uses.text = true; }, ScalarDefinitionV1::Code { .. } | ScalarDefinitionV1::TypedId { .. } => { uses.string = true; uses.pattern = true; }, ScalarDefinitionV1::Enum { .. } => uses.string = true } }
    uses.string |= !catalog.tagged_unions().is_empty();
    for field in catalog.records().iter().flat_map(|record| record.fields()) { match field.kind() {
        ResolvedFieldKindV1::LegacyValue => match strict_legacy_value(field.definition().field_type) { StrictLegacyValue::String(_) | StrictLegacyValue::OptionalString(_) => { uses.string = true; uses.pattern = true; uses.legacy_string = true; }, StrictLegacyValue::Schema | StrictLegacyValue::Enum(..) => uses.string = true, StrictLegacyValue::Uint | StrictLegacyValue::OptionalUint => uses.integer = true, StrictLegacyValue::Bool => uses.boolean = true, StrictLegacyValue::StringArray(_, maximum, unique) => { uses.arrays = true; uses.collect_array |= maximum == 0; uses.string = true; uses.pattern = true; uses.legacy_string = true; uses.bounds |= maximum != 0; uses.unique |= unique; }, StrictLegacyValue::EnumArray(..) => { uses.arrays = true; uses.collect_array = true; uses.string = true; }, StrictLegacyValue::OpenRefused | StrictLegacyValue::NotLegacyValue => {} },
        ResolvedFieldKindV1::LegacyReference { shape: LegacyReferenceShapeV1::Array, .. } => { uses.arrays = true; if field.definition().field_type == FieldTypeV1::ExecutionToolArray { uses.bounds = true; uses.unique = true; } else { uses.collect_array = true; } },
        ResolvedFieldKindV1::LegacyReference { .. } | ResolvedFieldKindV1::Named(_) | ResolvedFieldKindV1::OptionalNamed(_) => {},
        ResolvedFieldKindV1::BoundedArray { .. } => { uses.arrays = true; uses.bounds = true; uses.bounded_array = true; uses.rebase = true; },
        ResolvedFieldKindV1::BoundedSet { .. } => { uses.arrays = true; uses.bounds = true; uses.bounded_set = true; uses.rebase = true; uses.set = true; },
    } }
    uses
}

