#[rustfmt::skip]
fn rust_strict_legacy_collect(field_type: FieldTypeV1) -> Result<String, WireError> {
    Ok(match strict_legacy_value(field_type) {
        StrictLegacyValue::String(rule) => format!("bullet_generated_legacy_string(value, path, \"{rule}\")?"),
        StrictLegacyValue::Schema => "match bullet_generated_string(value, path)?.as_str() { \"v1alpha1\" => SchemaVersionLiteralV1::V1alpha1, _ => return Err(bullet_generated_error(path)) }".into(),
        StrictLegacyValue::Enum(name, values) => rust_strict_enum_expression(name, values),
        StrictLegacyValue::Uint => "u64::try_from(bullet_generated_integer(value, path)?).map_err(|_| bullet_generated_error(path))?".into(),
        StrictLegacyValue::OptionalUint => "match value { BulletGeneratedUniqueJsonValueV1::Null => None, value => Some(u64::try_from(bullet_generated_integer(value, path)?).map_err(|_| bullet_generated_error(path))?) }".into(),
        StrictLegacyValue::OptionalString(rule) => format!("match value {{ BulletGeneratedUniqueJsonValueV1::Null => None, value => Some(bullet_generated_legacy_string(value, path, \"{rule}\")?) }}"),
        StrictLegacyValue::Bool => "bullet_generated_bool(value, path)?".into(),
        StrictLegacyValue::StringArray(rule, 0, false) => format!("bullet_generated_collect_array(value, path, |value, path| bullet_generated_legacy_string(value, path, \"{rule}\"))?"),
        StrictLegacyValue::StringArray(rule, maximum, unique) => format!("{{ let nodes = bullet_generated_array(value, path)?; bullet_generated_cardinality(nodes.len(), 0, {maximum}, path)?; let duplicate = {} let values = match bullet_generated_collect_nodes(nodes, path, |value, path| bullet_generated_legacy_string(value, path, \"{rule}\")) {{ Ok(values) => values, Err(error) => return Err(bullet_generated_choose(error, duplicate)) }}; if let Some(error) = duplicate {{ return Err(error); }} values }}", if unique { "bullet_generated_duplicate_failure(&nodes, path)?;" } else { "None;" }),
        StrictLegacyValue::EnumArray(name, values) => format!("bullet_generated_collect_array(value, path, |value, path| Ok({}))?", rust_strict_enum_expression(name, values)),
        StrictLegacyValue::OpenRefused | StrictLegacyValue::NotLegacyValue => return Err(impossible_field()),
    })
}

