#[rustfmt::skip]
fn rust_strict_enum_expression(name: &str, values: &str) -> String {
    format!("{{ let item = bullet_generated_string(value, path)?; match item.as_str() {{ {} _ => return Err(bullet_generated_error(path)), }} }}", values.split_ascii_whitespace().map(|value| format!("\"{value}\" => {name}::{},", if value == "paseto-v4.public" { "PasetoV4Public".into() } else { rust_variant_identifier(value) })).collect::<String>())
}

#[rustfmt::skip]
fn typescript_strict_enum_expression(values: &str, value: &str, path: &str) -> String {
    format!("(() => {{ const item = bulletGeneratedString({value}, {path}); switch (item) {{ {} default: return bulletGeneratedFail({path}); }} }})()", values.split_ascii_whitespace().map(|item| format!("case \"{item}\": return item; ")).collect::<String>())
}
